# Substrate §3.1 — Privacy / Redaction Gate (stub).
import re
env = dict(input) if isinstance(input, dict) else {"raw": input}

def _redact(text):
    if not isinstance(text, str):
        return text
    text = re.sub(r"\b[\w.+-]+@[\w-]+\.[\w.-]+\b", "[email]", text)
    text = re.sub(r"\b\d{3}-\d{2}-\d{4}\b",          "[ssn]",   text)
    text = re.sub(r"\b\d{13,19}\b",                  "[card]",  text)
    return text

def _walk(v):
    if isinstance(v, str):  return _redact(v)
    if isinstance(v, list): return [_walk(x) for x in v]
    if isinstance(v, dict): return {k: _walk(x) for k, x in v.items()}
    return v

for key in ("payload", "raw", "body", "message", "observation"):
    if key in env:
        env[key] = _walk(env[key])
env.setdefault("provenance", []).append({"stage": "privacy", "redacted": True})
output = env

# Substrate §3.1 — Adversarial-Input Filter (stub).
env = dict(input) if isinstance(input, dict) else {"raw": input}
payload = None
for key in ("payload", "raw", "body", "message"):
    if key in env:
        payload = env.pop(key)
        break
env["untrusted_content"] = payload
env.setdefault("provenance", []).append({"stage": "adversarial", "wrapped": True})
output = env

# Conscious agent — Anticipatory (stub). Reads the most recent
# observation from the World Model and decides whether to propose an
# intent. Maps subject keywords to capabilities; in production this is
# an `agent_flow` driven by a model that consults Goal Hierarchy +
# Vitals + recent Ledger to pick the right action.
env = dict(input) if isinstance(input, dict) else {"raw": input}
obs = env.get("observation") or {}
subject = (obs.get("subject") or "").lower()

intent = None
if ("wire" in subject) or ("urgent" in subject) or ("transfer" in subject):
    intent = {
        "capability": "core.transfer_funds",
        "rationale": "Subject indicates a high-stake monetary action; escalate for explicit consent.",
        "args":      {"amount": None, "recipient": None},
    }
elif ("calendar" in subject) or ("meeting" in subject) or ("reminder" in subject):
    intent = {
        "capability": "core.notify",
        "rationale": "Calendar event detected; nudge the user.",
        "args":      {"message": f"Heads up: {obs.get('subject')}"},
    }

if intent:
    env["intent"] = intent
    env.setdefault("provenance", []).append({"stage": "conscious_anticipate",
                                              "emitted_intent": intent["capability"]})
else:
    env.setdefault("provenance", []).append({"stage": "conscious_anticipate",
                                              "emitted_intent": None})
output = env

# Substrate §3.4 — Capability Registry lookup.
env  = dict(input) if isinstance(input, dict) else {"raw": input}
caps = variables.setdefault("capabilities", {})
if not caps:
    caps["core.notify"] = {
        "name":          "core.notify",
        "purpose":       "Surface a UI notification to the user",
        "scopes":        ["read-only"],
        "latency_tier":  "interactive",
        "cost_estimate": 0.0,
    }
    caps["core.send_email"] = {
        "name":          "core.send_email",
        "purpose":       "Send an outbound email",
        "scopes":        ["write", "external-network", "affects-third-party"],
        "latency_tier":  "responsive",
        "cost_estimate": 0.001,
    }
    caps["core.transfer_funds"] = {
        "name":          "core.transfer_funds",
        "purpose":       "Initiate a money transfer",
        "scopes":        ["spends-money", "write", "affects-third-party"],
        "latency_tier":  "responsive",
        "cost_estimate": 0.5,
    }

intent   = env.get("intent") or {}
cap_name = intent.get("capability")
if cap_name and cap_name in caps:
    cap = caps[cap_name]
    env["resolved_capability"] = {
        "name":         cap_name,
        "scopes":       cap["scopes"],
        "latency_tier": cap["latency_tier"],
    }
    env["scopes"] = sorted(set(list(env.get("scopes", [])) + list(cap["scopes"])))
    env.setdefault("provenance", []).append({"stage": "capability_registry", "resolved": cap_name})
else:
    env.setdefault("provenance", []).append({"stage": "capability_registry", "resolved": None})
output = env

# Substrate §3.5 — Governor decision over the merged envelope.
# Note: Phase 2 stub reuses one Governor pass for the observation +
# intent. Phase 3 hardening will gate the observation and the intent
# independently for defense-in-depth.
env    = dict(input) if isinstance(input, dict) else {"raw": input}
scopes = list(env.get("scopes", ["read-only"]))
conf   = float(env.get("confidence", 1.0))

HIGH_STAKE = {"spends-money", "impersonates-user", "affects-third-party"}
WRITE      = {"write"}

if any(s in HIGH_STAKE for s in scopes):
    decision, reason = "consent_required", "high-stake scope present"
elif any(s in WRITE for s in scopes) and conf < 0.85:
    decision, reason = "consent_required", "write at low confidence"
else:
    decision, reason = "allow", "low-class action"

env["governor_verdict"] = {
    "decision":   decision,
    "reason":     reason,
    "scopes":     scopes,
    "confidence": conf,
}
output = env
